Think: Coerce the trimmed normalized value into a canonical numeric string (handle integers and simple decimals), save it to temp_check/canonical_numeric.txt, and record whether it changed compared to the trimmed original in temp_check/coercion_log.txt.

Act: bash

```bash
awk '{
  s=$0;
  gsub(/^[ \t]+|[ \t]+$/,"",s);
  orig=s;
  sign="";
  if (s ~ /^[+-].*/) { sign=substr(s,1,1); s=substr(s,2) }
  if (s ~ /^[0-9]+$/) {
    gsub(/^0+/,"",s);
    if (s=="") s="0";
    out = sign s;
  } else if (s ~ /^[0-9]*\.[0-9]+$/ || s ~ /^[0-9]+\.[0-9]*$/) {
    split(s,a,".");
    ip=a[1]; fp=a[2];
    if (ip=="") ip="0";
    gsub(/^0+/,"",ip);
    if (ip=="") ip="0";
    while (fp != "" && substr(fp,length(fp),1)=="0") fp=substr(fp,1,length(fp)-1);
    if (fp=="") out = sign ip; else out = sign ip "." fp;
  } else {
    out = orig;
  }
  print out > "temp_check/canonical_numeric.txt";
  if (out != orig) print "changed" > "temp_check/coercion_log.txt"; else print "unchanged" > "temp_check/coercion_log.txt";
}' temp_check/normalized_var.txt
```

